look.customCSS:
/* ───── 雨天窗边 · 第一批 ───── */
[data-wk="chat"]{background:url("data:image/svg+xml;base64,") 0 0/390px 520px repeat,linear-gradient(180deg,#141C44 0%,#1B2552 25%,#3B3F8C 55%,#7A5FC0 80%,#E59AC4 100%) !important;position:relative !important}
/* 雨丝往下落 */
[data-wk="chat"]::before{content:"" !important;position:absolute !important;inset:0 !important;background:url("data:image/svg+xml;base64,") 0 0/120px 160px repeat,url("data:image/svg+xml;base64,") 50px 30px/170px 220px repeat !important;pointer-events:none !important;z-index:0 !important;animation:rwRain 1.4s linear infinite !important}
@keyframes rwRain{from{background-position:0 0,50px 30px}to{background-position:-40px 160px,10px 250px}}
/* 窗外楼群＋窗台（抬到底栏上面露出来） */
[data-wk="chat"]::after{content:"" !important;position:absolute !important;left:0 !important;right:0 !important;bottom:0 !important;height:calc(env(safe-area-inset-bottom) * .4 + 62px + 150px) !important;background:url("data:image/svg+xml;base64,") center bottom calc(env(safe-area-inset-bottom) * .4 + 30px)/100% auto no-repeat,linear-gradient(#E9D3C2,#E9D3C2) center bottom/100% calc(env(safe-area-inset-bottom) * .4 + 34px) no-repeat !important;pointer-events:none !important;z-index:0 !important}
@media (prefers-reduced-motion:reduce){[data-wk="chat"]::before{animation:none !important}}
[data-wk="body"]{background:transparent !important;position:relative !important;z-index:1 !important;padding-top:40px !important}

/* 顶栏：深夜蓝磨砂，下沿挂一排小云、云底吊彩色雨滴 */
[data-wk="chathead"]{background:rgba(20,28,68,.78) !important;backdrop-filter:blur(8px) !important;-webkit-backdrop-filter:blur(8px) !important;border-bottom:1.5px solid rgba(200,178,255,.5) !important;box-shadow:none !important;position:relative !important;z-index:5 !important;overflow:visible !important}
[data-wk="chathead"]::after{content:"" !important;position:absolute !important;left:0 !important;right:0 !important;top:calc(100% - 6px) !important;height:52px !important;background:url("data:image/svg+xml;base64,") center top/100% auto no-repeat !important;pointer-events:none !important;transform-origin:center top !important;animation:rwSway 5s ease-in-out infinite !important}
@keyframes rwSway{0%,100%{transform:translateY(0)}50%{transform:translateY(2px)}}
[data-wk="chathead"] + *:not([data-wk="body"]){margin-top:34px !important}
[data-wk="headink"],[data-wk="headink"] *{color:#fff !important}
[data-wk="headdim"]{color:#C9D3F2 !important;white-space:nowrap !important}
[data-wk="chatback"] svg,[data-wk="headdim"] svg{stroke:#fff !important}
[data-wk="sameroom"]{width:36px !important;min-width:36px !important;height:36px !important;font-size:0 !important;padding:0 !important;background:url("data:image/svg+xml;base64,") center/34px no-repeat !important;border:none !important;box-shadow:none !important;margin-left:auto !important}
[data-wk="chatmore"]{width:52px !important;min-width:52px !important;height:34px !important;font-size:0 !important;color:transparent !important;padding:0 !important;background:url("data:image/svg+xml;base64,") center/48px auto no-repeat !important;border:none !important;box-shadow:none !important}
[data-wk="chatmore"] *,[data-wk="sameroom"] *{opacity:0 !important}
/* 顶栏头像撑一把小粉伞 */
[data-wk="chathead"] button:has(> [data-wk="avatar"]){position:relative !important;overflow:visible !important}
[data-wk="chathead"] button:has(> [data-wk="avatar"]) > [data-wk="avatar"]{box-shadow:0 0 0 2.5px #fff,0 0 12px rgba(143,194,255,.7) !important;border-radius:50% !important}
[data-wk="chathead"] button:has(> [data-wk="avatar"])::before{content:"" !important;position:absolute !important;width:40px !important;height:34px !important;left:-12px !important;top:calc(50% - 38px) !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;filter:drop-shadow(0 2px 2px rgba(0,0,0,.3)) !important;transform:rotate(-20deg) !important;z-index:3 !important;pointer-events:none !important}

/* 聊天头像：白圈＋底下托一朵小云 */
button[data-wk="avatar"],span[data-wk="avatar"]{position:relative !important;overflow:visible !important;isolation:isolate !important;border-radius:50% !important}
button[data-wk="avatar"] > *,span[data-wk="avatar"] > *,img[data-wk="avatar"]{position:relative !important;z-index:1 !important;border-radius:50% !important}
button[data-wk="avatar"],span[data-wk="avatar"]:not([data-halo]){box-shadow:0 0 0 2.5px #fff,0 0 10px rgba(183,156,255,.8) !important}
button[data-wk="avatar"]::after,span[data-wk="avatar"]:not([data-halo])::after{content:"" !important;position:absolute !important;left:-18% !important;right:-18% !important;bottom:-22% !important;height:46% !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCA2MCAyMic+PHBhdGggZD0nTTYgMjAgYTcgNyAwIDAgMSA0LTEyIGExMCAxMCAwIDAgMSAxOC00IGExMSAxMSAwIDAgMSAyMCAzIGE3IDcgMCAwIDEgNiAxMyBaJyBmaWxsPScjZmZmJyBzdHJva2U9JyNDOEIyRkYnIHN0cm9rZS13aWR0aD0nMS40Jy8+PC9zdmc+") center bottom/contain no-repeat !important;z-index:2 !important;pointer-events:none !important}
[data-wk="chathead"] button[data-wk="avatar"]::after,[data-wk="chathead"] span[data-wk="avatar"]::after{content:none !important}

/* 我的话：蓝到淡紫的玻璃，右上一串水珠，一颗水珠沿右边慢慢淌下来 */
[data-wk="bubble"][data-kind="text"]{position:relative !important;overflow:visible !important;color:#34406A !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]{background:linear-gradient(160deg,rgba(255,255,255,.75),rgba(255,255,255,0) 42%),linear-gradient(135deg,#9EC8FF,#C8B2FF) !important;border:2px solid rgba(255,255,255,.9) !important;border-radius:22px 22px 6px 22px !important;box-shadow:0 0 0 1.5px rgba(143,194,255,.6),0 6px 16px rgba(80,60,180,.35) !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]::before{content:"" !important;position:absolute !important;left:-12px !important;top:-10px !important;right:auto !important;bottom:auto !important;width:30px !important;height:23px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;border:none !important;transform:none !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]::after{content:"" !important;position:absolute !important;right:10px !important;top:4px !important;left:auto !important;bottom:auto !important;width:8px !important;height:11px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;border:none !important;transform:none !important;animation:rwSlide 6s ease-in infinite !important}
@keyframes rwSlide{0%,40%{transform:translateY(0);opacity:0}50%{opacity:1}90%{transform:translateY(calc(100% + 18px));opacity:1}100%{transform:translateY(calc(100% + 22px));opacity:0}}
[data-first="0"] [data-wk="bubble"][data-kind="text"][data-me="1"]::before{content:none !important}

/* 他的话：一张奶白卡，从一朵笑脸小云底下吊下来；连发的后几张只用一根细线挂在上一张底下 */
[data-wk="bubble"][data-kind="text"][data-me="0"]{background:#FFFBF4 !important;border:2px solid #C8B2FF !important;border-radius:8px 22px 22px 22px !important;box-shadow:0 4px 0 rgba(183,156,255,.55),0 8px 16px rgba(20,28,68,.35) !important;margin-top:16px !important;transform-origin:24px -16px !important;animation:rwSwing 5s ease-in-out infinite !important}
@keyframes rwSwing{0%,100%{transform:rotate(-1deg)}50%{transform:rotate(1deg)}}
[data-wk="bubble"][data-kind="text"][data-me="0"]::before{content:"" !important;position:absolute !important;left:-10px !important;top:-18px !important;right:auto !important;bottom:auto !important;width:44px !important;height:29px !important;z-index:2 !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;border:none !important;transform:none !important;pointer-events:none !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]::after{content:"" !important;position:absolute !important;right:-9px !important;left:auto !important;bottom:-9px !important;top:auto !important;width:20px !important;height:20px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAyNCAyNCc+PHBhdGggZD0nTTEyIDIgTDE0LjYgOS40IEwyMiAxMiBMMTQuNiAxNC42IEwxMiAyMiBMOS40IDE0LjYgTDIgMTIgTDkuNCA5LjRaJyBmaWxsPScjRkZEODZCJyBzdHJva2U9JyNmZmYnIHN0cm9rZS13aWR0aD0nMS40JyBzdHJva2UtbGluZWpvaW49J3JvdW5kJy8+PC9zdmc+") center/contain no-repeat !important;border:none !important;transform:none !important}
[data-first="0"] [data-wk="bubble"][data-kind="text"][data-me="0"]{margin-top:10px !important;animation:none !important}
[data-first="0"] [data-wk="bubble"][data-kind="text"][data-me="0"]::before{top:-14px !important;left:22px !important;width:2px !important;height:14px !important;background:#C8B2FF !important;border-radius:1px !important}
[data-msg] [data-wk="bubble"][data-kind="text"][data-me="0"]::after,[data-wk="msg"][data-last="0"] [data-wk="bubble"][data-kind="text"][data-me="0"]::after{content:none !important}

/* 时间：一朵白云胶囊 */
[data-wk="time"]{margin-top:20px !important}
[data-wk="time"] > span{min-width:150px !important;background:url("data:image/svg+xml;base64,") center/100% 100% no-repeat !important;border:none !important;border-radius:0 !important;padding:7px 22px 5px !important;color:#34406A !important;font-weight:600 !important;letter-spacing:.08em !important;box-shadow:none !important}
/* 已读：前面一颗小水滴 */
[data-wk="meta"]{color:#C9D3F2 !important;font-size:10.5px !important}
[data-wk="meta"][data-read="1"]::before{content:"" !important;display:inline-block !important;width:9px !important;height:12px !important;margin-right:4px !important;vertical-align:-2px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;filter:drop-shadow(0 0 3px rgba(143,194,255,.9)) !important}
[data-wk="msg"][data-last="0"] [data-wk="meta"]{display:none !important}
[data-wk="bubble"][data-kind="typing"]{background:#FFFBF4 !important;border:2px solid #C8B2FF !important;border-radius:8px 22px 22px 22px !important}
[data-wk="bubble"][data-kind="typing"]::before,[data-wk="bubble"][data-kind="typing"]::after{content:none !important}
[data-wk="typingdot"]{width:8px !important;height:11px !important;border-radius:0 !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="name"]{color:#fff !important}

/* 动描：像用手指写在起雾玻璃上——磨砂透明一条，白色斜体字，左边一道往下淌的水痕 */
[data-wk="narr"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="narrink"]{background:rgba(255,255,255,.14) !important;backdrop-filter:blur(4px) !important;-webkit-backdrop-filter:blur(4px) !important;border:1px solid rgba(255,255,255,.35) !important;border-left:3px solid #8FC2FF !important;border-radius:4px 14px 14px 4px !important;box-shadow:none !important;color:#F1F4FF !important;font-style:italic !important;font-size:13px !important;padding:6px 12px !important}
/* 系统提示：不带框的一行小字，前面一把小伞 */
[data-wk="sysnote"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="sysnotelabel"]{display:none !important}
[data-wk="sysnotetext"]{background:transparent !important;border:none !important;color:#C9D3F2 !important;font-size:11.5px !important;font-style:normal !important;letter-spacing:.06em !important}
[data-wk="sysnotetext"]::before{content:"☂ " !important;color:#FF9EC8 !important}

/* 底栏：一只悬浮的磨砂玻璃胶囊，加号、输入、发送、回复全包进去 */
[data-wk="composer"]{background:transparent !important;border-top:none !important;position:relative !important;z-index:2 !important;align-items:center !important;gap:6px !important;padding-left:16px !important;padding-right:16px !important}
[data-wk="composer"]::before{content:"" !important;position:absolute !important;left:6px !important;right:6px !important;top:2px !important;bottom:calc(env(safe-area-inset-bottom) * .4 + var(--composer-lift, 0px) - 8px) !important;border-radius:999px !important;background:linear-gradient(180deg,#FFFFFF,#F1ECFF) !important;border:2px solid #C8B2FF !important;box-shadow:0 4px 0 rgba(183,156,255,.6),0 8px 18px rgba(20,28,68,.35) !important;pointer-events:none !important;z-index:-1 !important}
[data-wk="chatinput"]{background:transparent !important;border:none !important;color:#34406A !important}
[data-wk="chatinput"]::placeholder{color:#9A92C4 !important}
[data-wk="chatplus"],[data-wk="send"],[data-wk="chatreply"]{border:none !important;box-shadow:none !important;border-radius:0 !important;width:36px !important;height:36px !important;min-width:36px !important;align-self:center !important;margin:0 !important;background-color:transparent !important}
[data-wk="chatplus"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="send"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;opacity:1 !important;filter:drop-shadow(0 0 6px rgba(255,158,200,.7)) !important}
[data-wk="chatreply"]{width:40px !important;min-width:40px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;margin-right:4px !important}
[data-wk="chatplus"] *,[data-wk="send"] *,[data-wk="chatreply"] *{opacity:0 !important}
[data-wk="chatplus"]:active,[data-wk="send"]:active,[data-wk="chatreply"]:active{transform:scale(.86) !important}
[data-wk="chatpanel"]{background:rgba(20,28,68,.92) !important;position:relative !important;z-index:3 !important;border-top:1.5px solid rgba(200,178,255,.5) !important}
